def largest_smallest_integers(lst):
    negative_max = max(x for x in lst if x < 0)
    positive_min = min(x for x in lst if x > 0)

    return (negative_max, positive_min)

```

```python

def largest_smallest_integers(lst):
    neg_max = max(lst) if any(x < 0 for x in lst) else None
    pos_min = min(lst) if any(x > 0 for x in lst) else None
    return (neg_max, pos_min)

```

```python

def largest_smallest_integers(lst):
    if not lst:
        return (None, None)
    max_negative = max([num for num in lst if num < 0])
    min_positive = min([num for num in lst if num > 0])
    return (max_negative, min_positive)

```

