def find_closest_elements(numbers: List[float]) -> Tuple[float, float]:
    sorted_numbers = sorted(numbers)
    small_element = float('inf')
    large_element = float('-inf')

    for i in numbers:
        if i < small_element:
            small_element = i

        if i > large_element:
            large_element = i

    return small_element, large_element
