    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if l == []:
        return True
    else:
        if len(l) == 1:
            return True
        else:
            for i in range(1, len(l)):
                if l[i] > l[i - 1]:
                    if l[i] >= l[i - 2]:
                        continue
                    else:
                        return False
                elif l[i] < l[i - 1]:
                    if l[i] <= l[i - 2]:
                        continue
                    else:
                        return False
                else:
                    continue
            return True


