from typing import *
from math import isqrt, sqrt

def is_prime(n: int) -> bool:
    """Check if a number is prime."""
    if n <= 1:
        return False
    for i in range(2, isqrt(n) + 1):
        if n % i == 0:
            return False
    return True


def prime_fib(n: int) -> int:
    """Return the n-th Fibonacci number that is also prime."""
    prime_fibonacci = 0
    a, b = 0, 1
    while prime_fibonacci < n:
        if is_prime(a):
            prime_fibonacci += 1
        a, b = b, a + b
    return a
