from typing import List

def factorial(i: int) -> int:
    """Calculate the factorial of i."""
    if i == 0:
        return 1
    return i * factorial(i - 1)

def sum_to(i: int) -> int:
    """Calculate the sum of numbers from 1 to i."""
    return i * (i + 1) // 2

def f(n: int) -> List[int]:
    """Return a list of size n, where the value of the element at index i is the factorial of i if i is even
    or the sum of numbers from 1 to i otherwise.
    """
    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_to(i))
    return result
