import re

def file_name_check(file_name):
    pattern = r'^[a-zA-Z][a-zA-Z0-9]{0,}[a-zA-Z0-9]{0,}[a-zA-Z0-9]{0,}$'
    if re.match(pattern, file_name):
        digits_count = sum(1 for char in file_name if char.isdigit())
        if digits_count > 3:
            return 'No'
        if '.' in file_name and len(file_name.split('.')[1]) > 3:
            return 'No'
        return 'Yes'
    else:
        return 'No'
