def unique_digits(x):
    """Given a list of positive integers x. return a sorted list of all 
    elements that hasn't any even digit.

    Note: Returned list should be sorted in increasing order.

    For example:
    >>> unique_digits([15, 33, 1422, 1])
    [1, 15, 33]
    >>> unique_digits([152, 323, 1422, 10])
    []
    """
    def is_valid_digit(digit):
        """Check if the digit is valid."""
        return digit % 2 != 0

    def dfs(nums, result):
        """Depth-first search to find all valid digits."""
        if not nums:
            return result
        for num in nums:
            num_str = str(num)
            if all(is_valid_digit(digit) for digit in num_str):
                result.append(num)
        return dfs([num for num in nums if num not in result], result)

    return sorted(dfs(x, []))

