def get_row(lst: List[List[int]], x: int) -> List[Tuple[int, int]]:
    row_coordinates = []
    for row_index, row in enumerate(lst):
        for col_index, value in enumerate(row):
            if value == x:
                row_coordinates.append((row_index, col_index))
    return sorted(row_coordinates, key=lambda coord: (coord[0], -coord[1]))
