from math import sqrt

def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        """Helper function to check if the given number is prime"""
        if n < 2:
            return False
        for i in range(2, int(sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    factors = [i for i in range(2, a) if a % i == 0 and is_prime(i)]
    prime_factors = {factors[i]*factors[i+1]*factors[i+2] for i in range(len(factors) - 2)}
    if a in prime_factors:
        return len(prime_factors) == 3 
    else:
        return False
