from typing import Optional

def compare_one(a: int | float | str, b: int | float | str) -> Optional[Union[int, float, str]]:
    if isinstance(a, str):
        a = float(a.replace(',', '.'))
    if isinstance(b, str):
        b = float(b.replace(',', '.'))

    if a > b:
        return a
    elif b > a:
        return b
    else:
        return None
