def decimal_to_binary(decimal):
    if decimal == 0:
        return "0db"  # Immediate return for decimal 0.
    binary_digits = ''
    while decimal > 0:
        binary_digits = str(decimal % 10) + binary_digits
        decimal //= 10
    return "db" + binary_digits + "db"

