def tri(n):
    result = []
    current, next, temp = 3, 1, 0

    for _ in range(n + 1):
        result.append(current)

        if _ % 2 == 0:
            current = 1 + _ // 2
        else:
            next, current = current + next + temp, next + temp, current + next

        temp = next

    return result

