def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def hex_key(num):
    """Count the number of hexadecimal digits that are prime.

    """
    hex_digits = '0123456789ABCDEF'
    prime_digits = '2357BD'
    count = 0
    for digit in num:
        if digit in prime_digits:
            count += 1
    return count
