def get_digit_name(digit):
    if digit == 1:
        return "One"
    elif digit == 2:
        return "Two"
    elif digit == 3:
        return "Three"
    elif digit == 4:
        return "Four"
    elif digit == 5:
        return "Five"
    elif digit == 6:
        return "Six"
    elif digit == 7:
        return "Seven"
    elif digit == 8:
        return "Eight"
    elif digit == 9:
        return "Nine"
    else:
        return "Invalid"

def by_length(arr):
    result = []
    for num in arr:
        if 1 <= num <= 9:
            digit_name = get_digit_name(num)
            result.append(digit_name)
    return result[::-1]
