import re

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def hex_key(num):
    prime_hex_digits = {'2', '3', '5', '7', 'B', 'D'}
    matches = re.findall(r'[0-9A-F]{1,2}', num)
    count = sum(is_prime(int(digit)) for digit in matches)
    return count
