import string

def encode(message):
    def letter_mapping(vowel):
        letters = string.ascii_lowercase
        return letters[(letters.index(vowel) + 3) % len(letters)]

    def swap_case(letter):
        return letter.swapcase()

    vowels = set('aeiouAEIOU')

    result = ''
    for char in message:
        if char in vowels:
            result += letter_mapping(char)
        else:
            result += swap_case(char)

    return result.strip()

# Test examples
