def solve(N):
    ones_list = []
    if N <= 1:
        return str(N)
    else:
        while N > 0:
            ones_list.append(N % 2)
            N //= 2
    ones_list.reverse()
    ones_list_sum = 0
    for num in ones_list:
        ones_list_sum += num
    return bin(ones_list_sum)[2:]


