def strange_sort_list(lst):
    def get_val(sorted_list, start, end):
        if start > end:
            return None
        elif start == end:
            return sorted_list[start]
        half = (start + end) // 2
        return sorted_list[start] if get_val(sorted_list, start + 1, half) is None else get_val(sorted_list, half + 1, end)

    length = len(lst)
    back = int((length - 1) // 2)
    for i in range(0, back, 2):
        # print(lst[i], lst[-(i + 1)])
        t1 = lst[i]
        t2 = lst[-(i + 1)]
        new = [t2] + lst[i + 1 : length - 1 : 2] + [t1] + lst[: i : 2]
        lst = [i for i in new if i != None] if new != None else lst
    return lst


