def sum_squares(lst):
    total = 0
    for i, num in enumerate(lst):
        if (i + 1) % 3 == 0 or (i + 1) % 4 == 0:
            if (i + 1) % 3 == 0:
                total += num ** 2
            else:
                total += num ** 3
        else:
            total += num
    return total
```

