from typing import List

def sum_squares(lst: List[int]):
    count = 0
    for index in range(1 if lst else 0, len(lst), 1):
        if (index + 1) % 3 == 0:
            count = count + pow(lst[index], 2)
        elif (index + 1) % 4 == 0:
            count = count + pow(lst[index], 3)
    return count
```

