def int_to_mini_roman(number):
    if not isinstance(number, int) or number < 1 or number > 1000:
        raise ValueError("Number should be between 1 and 1000")

    value = [100, 90, 50, 40, 10, 9, 5, 4, 1]
    numeral = ["cd", "xc", "l", "xl", "x", "ix", "v", "iv", "i"]

    roman_numeral = []
    for i in range(len(value)):
        this_num = number // value[i]
        number %= value[i]

        while this_num:
            roman_numeral.append(numeral[i])
            this_num -= 1

    return ''.join(roman_numeral).lower()

```

