def exchange(lst1, lst2):
    even_count = sum(1 for item in lst1 if item % 2 == 0)
    total_items = len(lst2)

    # To make lst1 have only even numbers, its even count must equal total items
    if even_count >= total_items:
        return "YES"
    else:
        return "NO"

