from typing import List
from bisect import bisect_left

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    min_path = []
    for i in range(n):
        for j in range(n):
            values = []
            for x in range(n):
                for y in range(n):
                    if x != i or y != j:
                        values.append(grid[x][y])
            values.sort()
            for _ in range(k):
                if not values:
                    break
                index = bisect_left(values, min_path[-1])
                if index == len(values):
                    min_path.append(values.pop(0))
                else:
                    min_path.append(values.pop(index))
    return min_path
