from typing import *

def can_arrange(arr: List[int]) -> int:
    stack = [-1]  # Initialize stack with -1 to handle the last element correctly
    for i, num in enumerate(arr):
        while arr[stack[-1]] < num:
            idx = stack.pop()  # Maintain stack to ensure precedence comparison
            if idx != -1:
                return idx
        stack.append(i)
    return -1
