    # Using Heron's formula to calculate the area of the triangle
    s = (a + b + c) / 2
    area = (s*(s-a)*(s-b)*(s-c)) ** 0.5

    # Return the area or -1.
    if area:
        return round(area, 2)
    else:
        return -1

