import string

def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    if n == 1:
        return 1

    # Count numbers that start with 1 and are n-digit
    count_start = 1
    for i in range(10, 10 ** n):
        if str(i).startswith('1'):
            count_start += 1

    # Count numbers that end with 1 and are n-digit
    count_end = 1
    for i in range(10, 10 ** n):
        if str(i)[-1] == '1':
            count_end += 1

    # Count numbers that are n-digit and start and end with 1
    count_both = 1
    for i in range(10, 10 ** n):
        if str(i).startswith('1') and str(i).endswith('1'):
            count_both += 1

    return count_start + count_end - count_both
```

