    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def hex_key(num):
    """Function to count the number of hexadecimal digits that are primes."""
    return sum(is_prime(int(digit, 16)) for digit in num)
