import heapq as heap

def maximum(arr, k):
    """
    Given an array arr of integers and a positive integer k, return a sorted list 
    of length k with the maximum k numbers in arr.

    """
    if k >= len(arr):
        return sorted(arr)

    heap_max = []
    for num in arr:
        if len(heap_max) < k:
            heap.heappush(heap_max, -num)
        else:
            if -num > heap_max[0]:
                heap_max[0] = -num
                heap.heappop(heap_max)
                heap.heappush(heap_max, -num)
    return [-x for x in heap_max]
