from typing import Union

def compare_one(a: Union[int, float, str]) -> Union[float, str, None]:
    """
    Compare two variables representing real numbers.
    Objects representing real numbers may look like integers, floats, or strings.
    Output the larger of the two in the same type. Return None if objects are equal:
    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    if isinstance(a, float) and isinstance(b, float):
        return max(a, b)
    if isinstance(a, str):
        try:
            str_a = float(a.replace(",", "."))
            return str(str_a if str_a == a else int(str_a))
        except:
            return None
    if isinstance(b, str):
        try:
            str_b = float(b.replace(",", "."))
            return str(str_b if str_b == b else int(str_b))
        except:
            return None
    return max(a, b)
