def count_nums(arr):
    """
    Write a function count_nums which takes an array of integers and returns
    the number of elements which has a sum of digits > 0.
    If a number is negative, then its first signed digit will be negative:
    e.g. -123 has signed digits -1, 2, and 3.
    >>> count_nums([]) == 0
    >>> count_nums([-1, 11, -11]) == 1
    >>> count_nums([1, 1, 2]) == 3
    """
    def sum_of_digits(n):
        """Helper function to calculate the sum of digits of a number or its signed digits."""
        if n < 0:
            return sum((-n % 10) for n in range(1, abs(n) + 1))
        else:
            return sum(n % 10 for n in range(1, n + 1))

    return sum(1 for n in arr if sum_of_digits(n) > 0)

