import re

def get_closest_vowel(word):
    vowels = "aeiouAEIOU"
    patterns = ["(.A*([aeiou]))", "(^([^aeiou]?.)[aeiou]$)", "(B[acd.mot]?E[A-cfjiopqtvul])", "\\.[U+zio+]"]
    closest_vowel = ""

    for pattern in patterns:
        match = re.match(pattern, word)
        if match:
            for group in match.groups()[1:]:
                if vowels.find(group) >= 0 and group != word[-1] and len(group) == 1:
                    closest_vowel = group
                    break

    return closest_vowel
