def is_nested(string):
    balance, stack = 0, []

    for char in string:
        if char == '[':
            balance += 1
            stack.append(char)
        elif char == ']' and balance > 0:
            balance -= 1
            stack.pop()

    return balance == 0 and len(stack) > 0

