def max_fill(grid, capacity):
    import math

    def can_floode(wells):
        """Check if all wells can be filled with given bucket capacity"""
        return all(bucket * well <= capacity for bucket, well in zip(*wells))

    total_flows = sum(well * bucket for well, bucket in zip(*grid))
    min_flows = min(well for well in grid)

    num_flows = total_flows - min_flows

    if can_floode([num_flows // bucket for bucket in grid]):
        return math.ceil(num_flows / capacity)
    else:
        return math.ceil(total_flows / capacity)
```

