def max_fill(grid, capacity):
    import math
    def dfs(grid, start, end, bucket):
        if start == end:
            return 0

        water = 0
        for i in range(start, end):
            water += sum(grid[i])

        if water <= bucket:
            return water

        min_water = water

        for i in range(start, end):
            for j in range(len(grid[i])):
                if grid[i][j] == 1:
                    grid[i][j] = 0
                    min_water = min(min_water, 1 + dfs(grid, start, i, bucket - grid[i].count(1)) + dfs(grid, i + 1, end, bucket))
                    grid[i][j] = 1

        return min_water

    total_drops = 0
    for i in range(len(grid)):
        total_drops += max(dfs(grid, i, len(grid), capacity), 0)

    return total_drops

```

