from typing import List

def rescale_to_unit(numbers: List[float]) -> List[float]:
    min_num = min(numbers)
    max_num = max(numbers)

    def transform_fn(x):
        return (x - min_num) / (max_num - min_num)

    return [transform_fn(num) for num in numbers]
