import re

def file_name_check(file_name):
    # Check constraints
    if not re.match("^[a-zA-Z][a-zA-Z-]*[a-zA-Z]*[a-zA-Z]*", file_name):
        return 'No'
    if re.match("(\\d){4,}", file_name):
