from typing import List

def count_nums(arr: List[int]) -> int:
    """
    Write a function count_nums which takes an array of integers and returns
    the number of elements which has a sum of digits > 0.
    If a number is negative, then its first signed digit will be negative:
    e.g. -123 has signed digits -1, 2, and 3.
    >>> count_nums([]) == 0
    >>> count_nums([-1, 11, -11]) == 1
    >>> count_nums([1, 1, 2]) == 3
    """
    def sum_digits(n):
        if n < 0:
            n = -n
            res = 0
            while n:
                res, n = res + n % 10, n // 10
            return -res
        else:
            return sum(int(digit) for digit in str(n))

    return sum(1 for i in arr if sum_digits(i) > 0 or i == 0)
```

```python
from typing import List

def count_nums(arr: List[int]) -> int:
    """
    Write a function count_nums which takes an array of integers and returns
    the number of elements which has a sum of digits > 0.
    If a number is negative, then its first signed digit will be negative:
    e.g. -123 has signed digits -1, 2, and 3.
    >>> count_nums([]) == 0
    >>> count_nums([-1, 11, -11]) == 1
    >>> count_nums([1, 1, 2]) == 3
    """
    def sum_of_digits(num: int) -> int:
        """Returns the sum of digits of num which handles negative numbers correctly."""
        num_str = str(num)
        if num < 0:
            return sum(int(num_str[1:]) if num_str else -sum(int(num) for num in reversed(num_str)))
        return sum(int(num_str))

    return sum(sum_of_digits(num) > 0 for num in arr)
```

