def encrypt(s):
    shift = 2 * 2
    encrypted = ''
    for char in s:
        if char.isalpha():
            shift_char = ord(char) + shift
            if char.islower():
                if shift_char > ord('z'):
                    shift_char -= 26
            else:
                if shift_char > ord('Z'):
                    shift_char -= 26
            encrypted += chr(shift_char)
        else:
            encrypted += char
    return encrypted
