from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    N = len(grid)
    dp = [[float('inf')] * (k + 1) for _ in range(N)]
    dp[0][0] = 0

    for j in range(1, k + 1):
        for i in range(N):
            for x in range(N):
                if i == x:
                    continue
                dp[i][j] = min(dp[i][j], dp[x][j - 1] + (grid[i][j] if i != x else float('inf')))

    return dp[N - 1][k]
```

