from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    result = []
    visited = [[False] * n for _ in range(n)]

    def dfs(x, y, path):
        if len(path) == k:
            result = path[:]
            return
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                dfs(nx, ny, path + [grid[nx][ny]])
                visited[nx][ny] = False

    for i in range(n):
        for j in range(n):
            visited[i][j] = True
            dfs(i, j, [grid[i][j]])
            visited[i][j] = False

    return result
