def prime_fib(n: int):
    a, b = 1, 1

    while True:
        if is_prime(a):
            if n == 1:
                return a
            n -= 1
        a, b = b, a + b

def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True
