import string

def encode(message):
    vowels = "aeiouAEIOU"
    def replace_vowel(vowel):
        if vowel in vowels:
            index = string.ascii_uppercase.index(vowel)
            if index == len(vowels) - 2:
                return "X"
            return string.ascii_uppercase[index + 2]
        return vowel

    def swap_case(letter):
        if letter.isupper():
            return letter.lower()
        return letter.upper()

    new_message = ""
    for char in message:
        if char.isalpha():
            new_message += swap_case(replace_vowel(char.lower()))
        else:
            new_message += char
    return new_message
