def specialFilter(nums):
    def is_odd_digits(num):
        while num > 0:
            digit = num % 10
            if digit % 2 == 0:
                return False
            num //= 10
        return True

    count = 0
    for num in nums:
        if 10 < num < 100 and is_odd_digits(num):
            count += 1
    return count
