import sys

def largest_smallest_integers(lst):
    negative_max = float('-inf')
    positive_min = float('inf')

    for num in lst:
        if num < 0:
            negative_max = max(negative_max, num)
        elif num > 0:
            positive_min = min(positive_min, num)

    if negative_max == float('-inf'):
        return (None, None)
    else:
        return (negative_max, positive_min)
