from functools import cache

def smallest_change(arr: List[int]) -> int:
    @cache
    def change_down(l: int, r: int) -> int:
        if l >= r:
            return 0
        if arr[l] != arr[r]:
            return (l + 1) + min(change_down(l + 1, r), change_down(l, r - 1))
        else:
            return change_down(l + 1, r - 1)

    return change_down(0, len(arr) - 1)
