import re

def solve(s):
    def reverse_case(char):
        return char.upper() if char.islower() else char.lower()

    letters = re.findall(r'[a-zA-Z]', s)

    result = []
    for char in s:
        if char in ('', '#', '@'):
            result.append(char)
        elif char.isalpha():
            result.append(reverse_case(char))
        else:
            result.append(char)[::-i]

    return ''.join(result)
