def solve(s):
    modified_string = []
    for char in s:
        if char.isalpha():
            modified_string.append(char.swapcase())
        else:
            modified_string.append(char)
    return "".join(modified_string)

# Examples
print(solve("1234")) # Output: "4321"
print(solve("ab")) # Output: "AB"
print(solve("#a@C")) # Output: "#A@c"
