import re

def match_parens(lst):
    count = 0
    for char in lst[0] + lst[1]:
        if char == '(':
            count += 1
        elif char == ')':
            count -= 1
        if count < 0:
            return 'No'
    return 'Yes' if count == 0 else 'No'
