import string

def rotate_letter(letter, rot):
    if letter.isalpha():
        alphabet = string.ascii_lowercase if letter.islower() else string.ascii_uppercase
        offset = rot % 26

        return alphabet[(alphabet.index(letter) - offset) % len(alphabet)]
    return letter

def encrypt(s):
    return ''.join(rotate_letter(char, 2 * 2) for char in s)
