import re

def Strongest_Extension(class_name, extensions):
    class_dependency_strength = {}

    for extension in extensions:
        strength = 0
        uppercase_count = 0
        lowercase_count = 0
        for char in extension:
            if char.isupper():
                uppercase_count += 1
            elif char.islower():
                lowercase_count += 1
            else:
                strength += 1
        class_dependency_strength[extension] = (uppercase_count - lowercase_count) / (len(extension) - strength)

    strongest_extension = max(class_dependency_strength, key=lambda x: class_dependency_strength[x])
    return f"{class_name}.{strongest_extension}"
