from typing import List


def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True


def words_in_sentence(sentence: str) -> List[str]:
    word_list = sentence.split(" ")
    primes_length_words = [word for word in word_list if is_prime(len(word))]
    return [*map(list, zip(*primes_length_words))]


