def check_if_last_char_is_a_letter(txt):
    ''' Create a function that returns True if the last character of a given string is an alphabetical character and is not a part of a word. '''

    import re

    # Cleaner implementation - filter out spaces first
    num_spaces = re.sub(r'\s', '', txt)

    if num_spaces:
        # Check the last alphanumeric character
        return bool(num_spaces[-1].isalpha())
    else: 
        return False  # Return False if no character is left, even if not alphabetical

