def get_closest_vowel(word):
    vowels = "aeiouAEIOU"
    left, right = -1, -1

    for i in range(len(word) - 1, 0, -1):
        if word[i] in vowels:
            if right == -1:
                right = i
            elif left == -1:
                left = i

    if left == -1 or right == -1:
        return ""

    return word[left:right]

