from string import ascii_lowercase, ascii_uppercase

def flip_case(string: str) -> str:
    flipped = ''
    for char in string:
        if char in ascii_lowercase:
            flipped += ascii_uppercase[ascii_lowercase.index(char)]
        elif char in ascii_uppercase:
            flipped += ascii_lowercase[ascii_uppercase.index(char)]
        else:
            flipped += char
    return flipped

