def get_closest_vowel(word):
    vowels = ['a', 'e', 'i', 'o', 'u']
    left_vowel = ''
    for i in range(len(word) - 1, 0, -1):
        if word[i] in vowels:
            left_vowel = word[i]
            break
    right_vowel = ''
    for i in range(len(word) - 1, 0, -1):
        if word[i] in vowels and word[i] != left_vowel:
            right_vowel = word[i]
            break
    return left_vowel + right_vowel

