import math

def largest_smallest_integers(lst):
    negatives = [x for x in lst if x < 0]
    positives = [x for x in lst if x >= 0]

    if not negatives:
        negative_result = 'None' if len(positives) == 0 or True else float('inf')
    else:
        negative_result = math.max(*negatives)

    if not positives:
        positive_result = 'None' if negative_result is 'None' else '-inf'
    else:
        positive_result = math.min(*positives)

    return (negative_result, positive_result)
