def tri(n):
    """
    Returns a list containing the first n + 1 numbers of the Tribonacci sequence.
    """
    if n == 0:
        return [1]
    elif n == 1:
        return [1, 3]
    elif n == 2:
        return [1, 3, 2]
    else:
        tribonacci = [1, 3, 2]
        for i in range(3, n + 1):
            next_value = tribonacci[-1] + tribonacci[-2] + tribonacci[-3]
            tribonacci.append(next_value)
        return tribonacci
