from typing import List

def factorial(n: int) -> int:
    """Helper function to calculate the factorial of n."""
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def sum_of_series(n: int) -> int:
    """Helper function to calculate the sum of numbers from 1 to n."""
    return n * (n + 1) // 2

def f(n: int) -> List[int]:
    """Returns a list of size n of the factorial or sum of numbers for even or odd index."""
    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_of_series(i))
    return result
