from math import log2

def move_one_ball(arr: List[int]) -> bool:
    if not arr:
        return True
    n = len(arr)
    for i in range(1, n):
        while arr[i] < arr[i-1]:
            for k in range(n-1, 0, -1):
                arr[k], arr[k-1] = arr[k-1], arr[k]
    return arr == sorted(arr)

