OPERATION = {
    '+': 'addition',
    '-': 'subtraction',
    '*': 'multiplication',
    '//': 'floordivision',
    '**': 'exponentiation'
}

def get_operator(op):
    return OPERATION.get(op)

def do_algebra(operator, operand):
    result = operand[0]
    for i in range(1, len(operand)):
        op = get_operator(operator[i])
        if op == 'addition':
            result += operand[i]
        elif op == 'subtraction':
            result -= operand[i]
        elif op == 'multiplication':
            result *= operand[i]
        elif op == 'floordivision':
            result //= operand[i]
        elif op == 'exponentiation':
            result **= operand[i]
    return result

