import string

def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = 'aeiouAEIOU'
    encoded_message = ''
    for char in message:
        if char.isalpha():
            if char.islower():
                if char in vowels:
                    encoded_message += string.ascii_lowercase[(vowels.index(char) + 2) % 5]
                else:
                    encoded_message += char.swapcase()
            else:
                if char in vowels:
                    encoded_message += string.ascii_uppercase[(vowels.index(char) + 2) % 5]
                else:
                    encoded_message += char.swapcase()
        else:
            encoded_message += char
    return encoded_message
