import string

def histogram(test):
    # Split the input string into a list of characters
    chars = test.split()
    count_dict = {}

    # Count the occurrences of each character
    for char in chars:
        if char in count_dict:
            count_dict[char] += 1
        else:
            count_dict[char] = 1

    # Find the most repeated character
    most_common_char = max(count_dict, key=count_dict.get)
    max_count = count_dict[most_common_char]

    # Return only the characters and counts of the most common one
    return {most_common_char: max_count}
