from collections import defaultdict

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    >>> histogram('a b c')
    {'a': 1, 'b': 1, 'c': 1}
    >>> histogram('a b b a')
    {'a': 2, 'b': 2}
    >>> histogram('a b c a b')
    {'a': 2, 'b': 2}
    >>> histogram('b b b b a')
    {'b': 4}
    >>> histogram('')
    {}
    """
    if not test: 
        return dict()
    else:
        letter_counts = defaultdict(int)
        for letter in test:
            letter_counts[letter] += 1
        most_common_letter_count = max(letter_counts.values())
        return {letter: count for letter, count in letter_counts.items() if count == most_common_letter_count}
