from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    def parse(inner_str: str) -> List[int]:
        depth = 0
        max_depth = 0
        left = 0
        result = []

        for char in inner_str:
            if char == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif char == ')':
                depth -= 1
            result.append(max_depth)

        return result

    output = [0 for _ in range(len(paren_string.split(" ")))]  # Initialize with 0 for each group

    for group in paren_string.split(" "):
        if "(" in group:  # Skip empty string input
            if group.count("(") > group.count(")"):
                output = []
            output.extend(parse(group))

    return output

