import math

def skjkasdkd(lst):
    """
    Finds the largest prime value in the given list and returns the sum of its digits.
    """
    def is_prime(n):
        """Helper function to check if a number is prime."""
        if n <= 1:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    largest_prime = -float('inf')
    for num in lst:
        if is_prime(num) and num > largest_prime:
            largest_prime = num

    if largest_prime == -float('inf'):
        return 0

    return sum(int(digit) for digit in str(largest_prime))
