from math import sqrt

def is_prime(n: int) -> bool:
    """ Determines if a given number is prime or not"""
    if n <= 1:
        return False
    if n == 2:
        return True  
    if n % 2 == 0:
        return False
    for i in range(3, int(sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True  

def skjkasdkd(lst: List[int]) -> int:
    """Return the sum of digits for the largest prime number in the input"""
    primes = [num for num in lst if is_prime(num)]
    max_prime = max(primes)
    return sum(map(int, str(max_prime))) 
