from typing import List

def parse_music(music_string: str) -> List[int]:
    """Converts a musical string with ASCII symbols encoded into a list of beats."""
    rhythms = music_string.split(' ')

    result = []
    for rhythm in rhythms:
        if rhythm == 'o':
            result.append(4)  # whole note takes 4 beats
        elif rhythm == 'o|':
            result.append(2)  # half note takes 2 beats
        elif rhythm == '.|':
            result.append(1)  # quarter note takes 1 beat

    return result
