from typing import *

def separate_paren_groups(paren_string: str) -> List[str]:
    parens = []
    group = []
    count = 0
    for char in paren_string:
        if char == "(":
            if count % 2 == 0:
                group.append('.')
            group.append(char)
            count += 1
        else:
            group.append(char)
            count -= 1
        if count == 0:
            parens.append(group)
            group = []
    return [item for item in paren_string if item != '.']
