def count_even_odd_palindromes(n):
    # Initialize counters for even and odd palindromes
    even_count = 0
    odd_count = 0

    # Generate all numbers from 1 to n inclusive
    for i in range(1, n + 1):
        str_i = str(i)

        # Check if the number is a palindrome
        if str_i == str_i[::-1]:

            # Check if the number is even or odd
            if int(str_i) % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)
