from sympy import isprime, fibonacci

def prime_fib(n: int):
    num_primes = 0
    num_fibs = 0

    while num_primes < n:
        num_fibs += 1
        if isprime(fibonacci(num_fibs)):
            num_primes += 1

    return fibonacci(num_fibs)
